<script setup>
import { computed, nextTick, onMounted, reactive, ref } from 'vue';
import { onBeforeRouteLeave } from 'vue-router';
import AdminNavigation from './AdminNavigation.vue';
import { activityTypes, formatPublicationDate, useEditorialStore } from '../stores/editorial';
const props = defineProps({ publication: Boolean });
const endpoint = props.publication ? 'publicaciones' : 'actividades';
const store = useEditorialStore();
const loading = ref(true), busy = ref(false), error = ref(''), notice = ref(''), fields = ref({}), editingId = ref(null), search = ref(''), state = ref('TODOS'), pending = ref(null), dialog = ref(null), formPanel = ref(null);
const today = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Guatemala', year:'numeric',month:'2-digit',day:'2-digit' }).format(new Date());
function blank() { return props.publication ? { titulo: '', descripcion: '', fechaPublicacion: today(), imagen: '', enlace: '', estado: 'ACTIVO' } : { titulo: '', descripcion: '', tipo: 'CAPACITACION', imagenes: ['/images/carrusel-familia.svg'], estado: 'ACTIVO' }; }
const form = reactive(blank());
const saved = ref(JSON.stringify(form));
const dirty = computed(() => saved.value !== JSON.stringify(form));
const visible = computed(() => [...store.adminItems[endpoint]].filter(item => (state.value === 'TODOS' || state.value === item.estado) && item.titulo.toLocaleLowerCase().includes(search.value.toLocaleLowerCase())).sort((a,b) => (props.publication ? b.fechaPublicacion.localeCompare(a.fechaPublicacion) : b.createdAt.localeCompare(a.createdAt)) || b._id.localeCompare(a._id)));
function reset() { editingId.value = null; Object.assign(form, blank()); saved.value = JSON.stringify(form); fields.value = {}; }
async function load() { loading.value = true; error.value = ''; try { await store.loadAdmin(endpoint); } catch (err) { error.value = err.message; } finally { loading.value = false; } }
function edit(item) { if (dirty.value && !window.confirm('¿Descartar los cambios sin guardar para editar otro contenido?')) return; const clean = Object.fromEntries(Object.keys(blank()).map(key => [key, Array.isArray(item[key]) ? [...item[key]] : item[key]])); Object.assign(form,clean); saved.value = JSON.stringify(form); editingId.value = item._id; error.value = ''; notice.value = ''; fields.value = {}; formPanel.value.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
function cancel() { if (!dirty.value || window.confirm('¿Descartar los cambios sin guardar?')) reset(); }
async function save() { busy.value = true; error.value = ''; notice.value = ''; fields.value = {}; const editing = Boolean(editingId.value); try { await store.save(endpoint, { ...form }, editingId.value); reset(); notice.value = editing ? 'Contenido actualizado.' : 'Contenido registrado.'; } catch (err) { error.value = err.message; fields.value = err.fields || {}; } finally { busy.value = false; } }
async function openState(item) { if (dirty.value) { error.value = 'Guarda o descarta los cambios del formulario antes de cambiar un estado.'; return; } pending.value = item; await nextTick(); dialog.value.showModal(); }
async function changeState() { busy.value = true; error.value = ''; notice.value = ''; try { await store.setState(endpoint, pending.value); if (editingId.value === pending.value._id) reset(); notice.value = pending.value.estado === 'ACTIVO' ? 'Contenido desactivado. Ya no aparece en el portal.' : 'Contenido activado. Ya aparece en el portal.'; } catch (err) { error.value = err.message; } finally { busy.value = false; pending.value = null; } }
function addImage() { if (form.imagenes.length < 5) form.imagenes.push(''); }
onBeforeRouteLeave(() => !busy.value && (!dirty.value || window.confirm('Tienes cambios sin guardar. ¿Quieres salir y descartarlos?')));
onMounted(load);
</script>
<template>
  <section class="page-heading"><p class="eyebrow">ADMINISTRACIÓN</p><h1>{{ publication ? 'Publicaciones educativas' : 'Actividades corporativas' }}</h1><p class="intro">{{ publication ? 'Comparte información y recursos con la comunidad.' : 'Administra capacitaciones, escuela para padres y otras actividades.' }}</p></section><AdminNavigation /><p class="dev-note">Edición habilitada únicamente mediante el acceso administrativo local de desarrollo.</p>
  <p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-if="notice" class="feedback success" role="status">{{ notice }}</p>
  <div class="admin-grid editorial-admin"><section ref="formPanel" class="form-panel"><h2>{{ editingId ? 'Editar contenido' : publication ? 'Nueva publicación' : 'Nueva actividad' }}</h2><form @submit.prevent="save"><fieldset :disabled="busy || loading"><legend class="sr-only">Datos del contenido</legend>
    <label for="editorial-titulo">Título</label><input id="editorial-titulo" v-model.trim="form.titulo" required maxlength="160" :aria-invalid="Boolean(fields.titulo)"><small v-if="fields.titulo" class="error">{{ fields.titulo }}</small>
    <label for="editorial-descripcion">Descripción</label><textarea id="editorial-descripcion" v-model.trim="form.descripcion" required maxlength="6000" rows="7" :aria-invalid="Boolean(fields.descripcion)"></textarea><small v-if="fields.descripcion" class="error">{{ fields.descripcion }}</small>
    <template v-if="publication"><label for="editorial-fecha">Fecha de publicación</label><input id="editorial-fecha" v-model="form.fechaPublicacion" type="date" required :aria-invalid="Boolean(fields.fechaPublicacion)"><small v-if="fields.fechaPublicacion" class="error">{{ fields.fechaPublicacion }}</small><label for="editorial-imagen">URL de imagen (opcional)</label><input id="editorial-imagen" v-model.trim="form.imagen" maxlength="2048" :aria-invalid="Boolean(fields.imagen)"><small v-if="fields.imagen" class="error">{{ fields.imagen }}</small><label for="editorial-enlace">Enlace al recurso (opcional)</label><input id="editorial-enlace" v-model.trim="form.enlace" type="url" maxlength="2048" placeholder="https://" :aria-invalid="Boolean(fields.enlace)"><small v-if="fields.enlace" class="error">{{ fields.enlace }}</small></template>
    <template v-else><label for="editorial-tipo">Tipo de actividad</label><select id="editorial-tipo" v-model="form.tipo"><option v-for="(label,key) in activityTypes" :key="key" :value="key">{{ label }}</option></select><small v-if="fields.tipo" class="error">{{ fields.tipo }}</small><div v-for="(image,index) in form.imagenes" :key="index" class="activity-image-field"><label :for="`actividad-imagen-${index}`">URL de imagen {{ index + 1 }}</label><div class="image-input-row"><input :id="`actividad-imagen-${index}`" v-model.trim="form.imagenes[index]" maxlength="2048" required><button class="text-button" type="button" :disabled="form.imagenes.length <= 1" :aria-label="`Quitar imagen ${index + 1}`" @click="form.imagenes.splice(index,1)">Quitar</button></div></div><button class="text-button add-image" type="button" :disabled="form.imagenes.length >= 5" @click="addImage">Agregar imagen</button><small v-if="fields.imagenes" class="error">{{ fields.imagenes }}</small></template>
    <small>Imágenes: URL HTTP/HTTPS o recursos locales en /images/.</small><label for="editorial-estado">Estado</label><select id="editorial-estado" v-model="form.estado"><option value="ACTIVO">Activo</option><option value="INACTIVO">Inactivo</option></select><small v-if="fields.estado" class="error">{{ fields.estado }}</small><div class="actions"><button class="button" :disabled="editingId && !dirty">{{ busy ? 'Guardando…' : editingId ? 'Guardar cambios' : 'Registrar contenido' }}</button><button v-if="editingId || dirty" type="button" class="button secondary" @click="cancel">{{ editingId ? 'Cancelar edición' : 'Limpiar formulario' }}</button></div></fieldset></form></section>
    <section class="list-panel"><h2>Contenido registrado</h2><div class="form-row"><div><label for="editorial-buscar">Buscar por título</label><input id="editorial-buscar" v-model="search" type="search"></div><div><label for="editorial-filtrar">Estado</label><select id="editorial-filtrar" v-model="state"><option value="TODOS">Todos</option><option value="ACTIVO">Activos</option><option value="INACTIVO">Inactivos</option></select></div></div><p v-if="loading" class="empty-state" role="status">Cargando contenido…</p><div v-else-if="error && !store.adminItems[endpoint].length" class="empty-state"><p>No se pudo cargar el listado.</p><button class="button secondary" @click="load">Reintentar</button></div><p v-else-if="!visible.length" class="empty-state">No hay contenido que mostrar.</p><ul v-else class="admin-services"><li v-for="item in visible" :key="item._id"><div class="service-line"><h3>{{ item.titulo }}</h3><span class="badge" :class="item.estado.toLowerCase()">{{ item.estado === 'ACTIVO' ? 'Activo' : 'Inactivo' }}</span></div><p>{{ publication ? formatPublicationDate(item.fechaPublicacion) : activityTypes[item.tipo] }}</p><div class="actions"><button class="text-button" :disabled="busy" :aria-label="`Editar ${item.titulo}`" @click="edit(item)">Editar</button><button class="text-button" :disabled="busy" :aria-label="`${item.estado === 'ACTIVO' ? 'Desactivar' : 'Activar'} ${item.titulo}`" @click="openState(item)">{{ item.estado === 'ACTIVO' ? 'Desactivar' : 'Activar' }}</button></div></li></ul></section>
  </div>
  <dialog v-if="pending" ref="dialog" class="confirm-panel" aria-labelledby="editorial-confirm" @cancel.prevent="!busy && (pending = null)"><h2 id="editorial-confirm">¿{{ pending.estado === 'ACTIVO' ? 'Desactivar' : 'Activar' }} contenido?</h2><p>{{ pending.titulo }}</p><p>{{ pending.estado === 'ACTIVO' ? 'Dejará de aparecer en el portal. El registro se conservará.' : 'Aparecerá en su sección del portal.' }}</p><div class="actions"><button class="button" :disabled="busy" @click="changeState">{{ busy ? 'Guardando…' : 'Confirmar' }}</button><button class="button secondary" :disabled="busy" autofocus @click="pending = null">Cancelar</button></div></dialog>
</template>
